text:
    p => !["number"].includes(p)
  );
  for (const param of params) {
    url.searchParams.delete(param);
  }
  const parentMsgHdr = Services.io
    .newURI(url.href)
    .QueryInterface(Ci.nsIMsgMessageUrl).messageHeader;
  return { msgHdr: parentMsgHdr, partName };
}

/**
 * @typedef {object} MimeTreePart - A mime part generated by jsmime using the
 *   MimeTreeEmitter (see MimeTree.sys.mjs).
 *
 * @property {string} partNum
 * @property {StructuredHeaders} headers - A Map, containing all headers. Special
 *   headers for contentType and charset.
 * @property {integer} size - Size of this part, including all subparts.
 * @property {string} body - Body
 * @property {string} [name] - The name, if this part is an attachment.
 * @property {boolean} [isAttachment] - The part is an attachment.
 * @property {MimeTreePart[]} subParts - Array of MimeTreePart with sub parts
 */

/**
 * Custom MimeTreeEmitter class with custom determination of attachment names.
 */
class WebExtMimeTreeEmitter extends MimeTreeEmitter {
  /**
   * Extract the attachment name of this part, if it is an attachment.
   *
   * Note: The content of parts which are _not_ considered to be attachments will
   * be included in the return value of messages.getFull().
   *
   * @param {MimeTreePart} mimeTreePart
   * @returns {?string} Name of the attachment, or null.
   */
  getAttachmentName(mimeTreePart) {
    const { mediatype, type } = mimeTreePart.headers.contentType;
    // Early exit on multipart parts.
    if (mediatype == "multipart") {
      return null;
    }

    let name;
    const contentDisposition = mimeTreePart.headers.get("content-disposition");
    if (contentDisposition) {
      name = lazy.MimeParser.getParameter(contentDisposition[0], "filename");
    }
    if (!name && mimeTreePart.fullContentType) {
      name = lazy.MimeParser.getParameter(mimeTreePart.fullContentType, "name");
    }
    if (!name) {
      name = "";
    }

    // Handle forwarded messages.
    if (type == "message/rfc822") {
      return name || "ForwardedMessage.eml";
    }

    // Handle deleted attachments.
    if (type == "text/x-moz-deleted") {
      return name;
    }

    // Handle related attachments, but skip if they do not have a name.
    if (name && mimeTreePart.headers._rawHeaders.has("content-id")) {
      return name;
    }

    // Skip text parts which are not clearly marked as attachments.
    if (
      mediatype == "text" &&
      (!contentDisposition || !/^attachment/i.test(contentDisposition[0]))
    ) {
      return null;
    }

    return name;
  }
}

